      setError(nameInput, true);
      isValid = false;
      if (isFirstError) {
        nameInput.focus();
        isFirstError = false;
      }
    } else {
      setError(nameInput, false);
    }

    // Validate Email
    if (!emailInput.value.trim() || !emailInput.validity.valid) {
      setError(emailInput, true);
      isValid = false;
      if (isFirstError) {
        emailInput.focus();
        isFirstError = false;
