document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('support-form');
  const nameInput = document.getElementById('fullName');
  const emailInput = document.getElementById('email');
  const phoneInput = document.getElementById('phone');

  const setError = (input, show) => {
    const describedBy = input.getAttribute('aria-describedby') || '';
    const errorId = describedBy.split(' ').find(id => id.includes('error'));
    if (!errorId) return;

    const errorMessage = document.getElementById(errorId);
    if (!errorMessage) return;

    if (show) {
      input.setAttribute('aria-invalid', 'true');
      errorMessage.removeAttribute('hidden');
    } else {
      input.removeAttribute('aria-invalid');
      errorMessage.setAttribute('hidden', '');
    }
  };

  const validatePhone = (phone) => {
    if (!phone) return true; // Optional
    // Allow digits, spaces, parentheses, dashes, plus sign
    const phoneRegex = /^(\+?\d{1,3}[\s-]?)?\(?\d{3}\)?[\s-]?\d{3}[\s-]?\d{4}$/;
    return phoneRegex.test(phone);
  };

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    let isFirstError = true;
    let isValid = true;

    // Validate Name
    if (!nameInput.value.trim()) {
      setError(nameInput, true);
      isValid = false;
      if (isFirstError) {
        nameInput.focus();
        isFirstError = false;
      }
    } else {
      setError(nameInput, false);
    }

    // Validate Email
    if (!emailInput.value.trim() || !emailInput.validity.valid) {
      setError(emailInput, true);
      isValid = false;
      if (isFirstError) {
        emailInput.focus();
        isFirstError = false;
      }
    } else {
      setError(emailInput, false);
    }

    // Validate Phone
    if (!validatePhone(phoneInput.value.trim())) {
      setError(phoneInput, true);
      isValid = false;
      if (isFirstError) {
        phoneInput.focus();
        isFirstError = false;
      }
    } else {
      setError(phoneInput, false);
    }

    if (isValid) {
      // Announce submission or simply reset
      alert('Form submitted successfully!');
      form.reset();
      [nameInput, emailInput, phoneInput].forEach(input => setError(input, false));
    }
  });

  // Clear error on input
  [nameInput, emailInput, phoneInput].forEach(input => {
    input.addEventListener('input', () => {
      if (input.getAttribute('aria-invalid') === 'true') {
        setError(input, false);
      }
    });
  });
});

